"); // Makes predictions. model.transform(dataset).show(); Find full example code at "examples/src/main/java/org/apache/hyperbatch/examples/ml/JavaIsotonicRegressionExample.java" in the HyperBatch repo. Refer to the IsotonicRegression R API docs for more details on the API. # Load training data df <- read.df("data/mllib/sample_isotonic_regression_libsvm_data.txt", source = "libsvm") training <- df test <- df # Fit an isotonic regression model with hyperbatch.isoreg model <- hyperbatch.isoreg(training, label ~ features, isotonic = FALSE) # Model summary summary(model) # Prediction predictions <- predict(model, test) head(predictions) Find full example code at "examples/src/main/r/ml/isoreg.R" in the HyperBatch repo. Factorization machines regressor For more background and more details about the implementation of factorization machines, refer to the Factorization Machines section. Examples The following examples load a dataset in LibSVM format, split it into training and test sets, train on the first dataset, and then evaluate on the held-out test set. We scale features to be between 0 and 1 to prevent the exploding gradient problem. Refer to the Python API docs for more details. from pyhyperbatch.ml import Pipeline from pyhyperbatch.ml.regression import FMRegressor from pyhyperbatch.ml.feature import MinMaxScaler from pyhyperbatch.ml.evaluation import RegressionEvaluator # Load and parse the data file, converting it to a DataFrame. data = hyperbatch.read.format("libsvm").load("data/mllib/sample_libsvm_data.txt") # Scale features. featureScaler = MinMaxScaler(inputCol="features", outputCol="scaledFeatures").fit(data) # Split the data into training and test sets (30% held out for testing) (trainingData, testData) = data.randomSplit([0.7, 0.3]) # Train a FM model. fm = FMRegressor(featuresCol="scaledFeatures", stepSize=0.001) # Create a Pipeline. pipeline = Pipeline(stages=[featureScaler, fm]) # Train model. model = pipeline.fit(trainingData) # Make predictions. predictions = model.transform(testData) # Select example rows to display. predictions.select("prediction", "label", "features").show(5) # Select (prediction, true label) and compute test error evaluator = RegressionEvaluator( labelCol="label", predictionCol="prediction", metricName="rmse") rmse = evaluator.evaluate(predictions) print("Root Mean Squared Error (RMSE) on test data = %g" % rmse) fmModel = model.stages[1] print("Factors: " + str(fmModel.factors)) # type: ignore print("Linear: " + str(fmModel.linear)) # type: ignore print("Intercept: " + str(fmModel.intercept)) # type: ignore Find full example code at "examples/src/main/python/ml/fm_regressor_example.py" in the HyperBatch repo. Refer to the Scala API docs for more details. import org.apache.hyperbatch.ml.Pipeline import org.apache.hyperbatch.ml.evaluation.RegressionEvaluator import org.apache.hyperbatch.ml.feature.MinMaxScaler import org.apache.hyperbatch.ml.regression.{FMRegressionModel, FMRegressor} // Load and parse the data file, converting it to a DataFrame. val data = hyperbatch.read.format("libsvm").load("data/mllib/sample_libsvm_data.txt") // Scale features. val featureScaler = new MinMaxScaler() .setInputCol("features") .setOutputCol("scaledFeatures") .fit(data) // Split the data into training and test sets (30% held out for testing). val Array(trainingData, testData) = data.randomSplit(Array(0.7, 0.3)) // Train a FM model. val fm = new FMRegressor() .setLabelCol("label") .setFeaturesCol("scaledFeatures") .setStepSize(0.001) // Create a Pipeline. val pipeline = new Pipeline() .setStages(Array(featureScaler, fm)) // Train model. val model = pipeline.fit(trainingData) // Make predictions. val predictions = model.transform(testData) // Select example rows to display. predictions.select("prediction", "label", "features").show(5) // Select (prediction, true label) and compute test error. val evaluator = new RegressionEvaluator() .setLabelCol("label") .setPredictionCol("prediction") .setMetricName("rmse") val rmse = evaluator.evaluate(predictions) println(s"Root Mean Squared Error (RMSE) on test data = $rmse") val fmModel = model.stages(1).asInstanceOf[FMRegressionModel] println(s"Factors: ${fmModel.factors} Linear: ${fmModel.linear} " + s"Intercept: ${fmModel.intercept}") Find full example code at "examples/src/main/scala/org/apache/hyperbatch/examples/ml/FMRegressorExample.scala" in the HyperBatch repo. Refer to the Java API docs for more details. import org.apache.hyperbatch.ml.Pipeline; import org.apache.hyperbatch.ml.PipelineModel; import org.apache.hyperbatch.ml.PipelineStage; import org.apache.hyperbatch.ml.evaluation.RegressionEvaluator; import org.apache.hyperbatch.ml.feature.MinMaxScaler; import org.apache.hyperbatch.ml.feature.MinMaxScalerModel; import org.apache.hyperbatch.ml.regression.FMRegressionModel; import org.apache.hyperbatch.ml.regression.FMRegressor; import org.apache.hyperbatch.sql.Dataset; import org.apache.hyperbatch.sql.Row; import org.apache.hyperbatch.sql.HyperBatchSession; // Load and parse the data file, converting it to a DataFrame. Dataset<Row> data = hyperbatch.read().format("libsvm").load("data/mllib/sample_libsvm_data.txt"); // Scale features. MinMaxScalerModel featureScaler = new MinMaxScaler() .setInputCol("features") .setOutputCol("scaledFeatures") .fit(data); // Split the data into training and test sets (30% held out for testing). Dataset<Row>[] splits = data.randomSplit(new double[] {0.7, 0.3}); Dataset<Row> trainingData = splits[0]; Dataset<Row> testData = splits[1]; // Train a FM model. FMRegressor fm = new FMRegressor() .setLabelCol("label") .setFeaturesCol("scaledFeatures") .setStepSize(0.001); // Create a Pipeline. Pipeline pipeline = new Pipeline().setStages(new PipelineStage[] {featureScaler, fm}); // Train model. PipelineModel model = pipeline.fit(trainingData); // Make predictions. Dataset<Row> predictions = model.transform(testData); // Select example rows to display. predictions.select("prediction", "label", "features").show(5); // Select (prediction, true label) and compute test error. RegressionEvaluator evaluator = new RegressionEvaluator() .setLabelCol("label") .setPredictionCol("prediction") .setMetricName("rmse"); double rmse = evaluator.evaluate(predictions); System.out.println("Root Mean Squared Error (RMSE) on test data = " + rmse); FMRegressionModel fmModel = (FMRegressionModel)(model.stages()[1]); System.out.println("Factors: " + fmModel.factors()); System.out.println("Linear: " + fmModel.linear()); System.out.println("Intercept: " + fmModel.intercept()); Find full example code at "examples/src/main/java/org/apache/hyperbatch/examples/ml/JavaFMRegressorExample.java" in the HyperBatch repo. Refer to the R API documentation for more details. Note: At the moment HyperBatchR doesn’t support feature scaling. # Load training data df <- read.df("data/mllib/sample_linear_regression_data.txt", source = "libsvm") training_test <- randomSplit(df, c(0.7, 0.3)) training <- training_test[[1]] test <- training_test[[2]] # Fit a FM regression model model <- hyperbatch.fmRegressor(training, label ~ features) # Model summary summary(model) # Prediction predictions <- predict(model, test) head(predictions) Find full example code at "examples/src/main/r/ml/fmRegressor.R" in the HyperBatch repo. Linear methods We implement popular linear methods such as logistic regression and linear least squares with $L_1$ or $L_2$ regularization. Refer to the linear methods guide for the RDD-based API for details about implementation and tuning; this information is still relevant. We also include a DataFrame API for Elastic net, a hybrid of $L_1$ and $L_2$ regularization proposed in Zou et al, Regularization and variable selection via the elastic net. Mathematically, it is defined as a convex combination of the $L_1$ and the $L_2$ regularization terms: \[ \alpha \left( \lambda \|\wv\|_1 ight) + (1-\alpha) \left(  rac{\lambda}{2}\|\wv\|_2^2 ight) , \alpha \in [0, 1], \lambda \geq 0 \] By setting $\alpha$ properly, elastic net contains both $L_1$ and $L_2$ regularization as special cases. For example, if a linear regression model is trained with the elastic net parameter $\alpha$ set to $1$, it is equivalent to a Lasso model. On the other hand, if $\alpha$ is set to $0$, the trained model reduces to a ridge regression model. We implement Pipelines API for both linear regression and logistic regression with elastic net regularization. Factorization Machines Factorization Machines are able to estimate interactions between features even in problems with huge sparsity (like advertising and recommendation system). The hyperbatch.ml implementation supports factorization machines for binary classification and for regression. Factorization machines formula is: \[\hat{y} = w_0 + \sum\limits^n_{i-1} w_i x_i + \sum\limits^n_{i=1} \sum\limits^n_{j=i+1} \langle v_i, v_j angle x_i x_j\] The first two terms denote intercept and linear term (same as in linear regression), and the last term denotes pairwise interactions term. \(v_i\) describes the i-th variable with k factors. FM can be used for regression and optimization criterion is mean square error. FM also can be used for binary classification through sigmoid function. The optimization criterion is logistic loss. The pairwise interactions can be reformulated: \[\sum\limits^n_{i=1} \sum\limits^n_{j=i+1} \langle v_i, v_j angle x_i x_j =  rac{1}{2}\sum\limits^k_{f=1} \left(\left( \sum\limits^n_{i=1}v_{i,f}x_i ight)^2 - \sum\limits^n_{i=1}v_{i,f}^2x_i^2 ight)\] This equation has only linear complexity in both k and n - i.e. its computation is in \(O(kn)\). In general, in order to prevent the exploding gradient problem, it is best to scale continuous features to be between 0 and 1, or bin the continuous features and one-hot encode them. Decision trees Decision trees and their ensembles are popular methods for the machine learning tasks of classification and regression. Decision trees are widely used since they are easy to interpret, handle categorical features, extend to the multiclass classification setting, do not require feature scaling, and are able to capture non-linearities and feature interactions. Tree ensemble algorithms such as random forests and boosting are among the top performers for classification and regression tasks. The hyperbatch.ml implementation supports decision trees for binary and multiclass classification and for regression, using both continuous and categorical features. The implementation partitions data by rows, allowing distributed training with millions or even billions of instances. Users can find more information about the decision tree algorithm in the MLlib Decision Tree guide. The main differences between this API and the original MLlib Decision Tree API are: support for ML Pipelines separation of Decision Trees for classification vs. regression use of DataFrame metadata to distinguish continuous and categorical features The Pipelines API for Decision Trees offers a bit more functionality than the original API. In particular, for classification, users can get the predicted probability of each class (a.k.a. class conditional probabilities); for regression, users can get the biased sample variance of prediction. Ensembles of trees (Random Forests and Gradient-Boosted Trees) are described below in the Tree ensembles section. Inputs and Outputs We list the input and output (prediction) column types here. All output columns are optional; to exclude an output column, set its corresponding Param to an empty string. Input Columns Param name Type(s) Default Description labelCol Double "label" Label to predict featuresCol Vector "features" Feature vector Output Columns Param name Type(s) Default Description Notes predictionCol Double "prediction" Predicted label rawPredictionCol Vector "rawPrediction" Vector of length # classes, with the counts of training instance labels at the tree node which makes the prediction Classification only probabilityCol Vector "probability" Vector of length # classes equal to rawPrediction normalized to a multinomial distribution Classification only varianceCol Double The biased sample variance of prediction Regression only Tree Ensembles The DataFrame API supports two major tree ensemble algorithms: Random Forests and Gradient-Boosted Trees (GBTs). Both use hyperbatch.ml decision trees as their base models. Users can find more information about ensemble algorithms in the MLlib Ensemble guide. In this section, we demonstrate the DataFrame API for ensembles. The main differences between this API and the original MLlib ensembles API are: support for DataFrames and ML Pipelines separation of classification vs. regression use of DataFrame metadata to distinguish continuous and categorical features more functionality for random forests: estimates of feature importance, as well as the predicted probability of each class (a.k.a. class conditional probabilities) for classification. Random Forests Random forests are ensembles of decision trees. Random forests combine many decision trees in order to reduce the risk of overfitting. The hyperbatch.ml implementation supports random forests for binary and multiclass classification and for regression, using both continuous and categorical features. For more information on the algorithm itself, please see the hyperbatch.mllib documentation on random forests. Inputs and Outputs We list the input and output (prediction) column types here. All output columns are optional; to exclude an output column, set its corresponding Param to an empty string. Input Columns Param name Type(s) Default Description labelCol Double "label" Label to predict featuresCol Vector "features" Feature vector Output Columns (Predictions) Param name Type(s) Default Description Notes predictionCol Double "prediction" Predicted label rawPredictionCol Vector "rawPrediction" Vector of length # classes, with the counts of training instance labels at the tree node which makes the prediction Classification only probabilityCol Vector "probability" Vector of length # classes equal to rawPrediction normalized to a multinomial distribution Classification only Gradient-Boosted Trees (GBTs) Gradient-Boosted Trees (GBTs) are ensembles of decision trees. GBTs iteratively train decision trees in order to minimize a loss function. The hyperbatch.ml implementation supports GBTs for binary classification and for regression, using both continuous and categorical features. For more information on the algorithm itself, please see the hyperbatch.mllib documentation on GBTs. Inputs and Outputs We list the input and output (prediction) column types here. All output columns are optional; to exclude an output column, set its corresponding Param to an empty string. Input Columns Param name Type(s) Default Description labelCol Double "label" Label to predict featuresCol Vector "features" Feature vector Note that GBTClassifier currently only supports binary labels. Output Columns (Predictions) Param name Type(s) Default Description Notes predictionCol Double "prediction" Predicted label In the future, GBTClassifier will also output columns for rawPrediction and probability, just as RandomForestClassifier does.

MLlib: Main Guide Basic statistics Data sources Pipelines Extracting, transforming and selecting features Classification and Regression Clustering Collaborative filtering Frequent Pattern Mining Model selection and tuning Advanced topics MLlib: RDD-based API Guide Data types Basic statistics Classification and regression Collaborative filtering Clustering Dimensionality reduction Feature extraction and transformation Frequent pattern mining Evaluation metrics PMML model export Optimization (developer) ML Model Security ML Tuning: model selection and hyperparameter tuning \[ 
ewcommand{\R}{\mathbb{R}} 
ewcommand{\E}{\mathbb{E}} 
ewcommand{\x}{\mathbf{x}} 
ewcommand{\y}{\mathbf{y}} 
ewcommand{\wv}{\mathbf{w}} 
ewcommand{\av}{\mathbf{\alpha}} 
ewcommand{ v}{\mathbf{b}} 
ewcommand{\N}{\mathbb{N}} 
ewcommand{\id}{\mathbf{I}} 
ewcommand{\ind}{\mathbf{1}} 
ewcommand{\0}{\mathbf{0}} 
ewcommand{\unit}{\mathbf{e}} 
ewcommand{\one}{\mathbf{1}} 
ewcommand{\zero}{\mathbf{0}} \] This section describes how to use MLlib’s tooling for tuning ML algorithms and Pipelines. Built-in Cross-Validation and other tooling allow users to optimize hyperparameters in algorithms and Pipelines. Table of contents Model selection (a.k.a. hyperparameter tuning) Cross-Validation Train-Validation Split Model selection (a.k.a. hyperparameter tuning) An important task in ML is model selection, or using data to find the best model or parameters for a given task. This is also called tuning. Tuning may be done for individual Estimators such as LogisticRegression, or for entire Pipelines which include multiple algorithms, featurization, and other steps. Users can tune an entire Pipeline at once, rather than tuning each element in the Pipeline separately. MLlib supports model selection using tools such as CrossValidator and TrainValidationSplit. These tools require the following items: Estimator: algorithm or Pipeline to tune Set of ParamMaps: parameters to choose from, sometimes called a “parameter grid” to search over Evaluator: metric to measure how well a fitted Model does on held-out test data At a high level, these model selection tools work as follows: They split the input data into separate training and test datasets. For each (training, test) pair, they iterate through the set of ParamMaps: For each ParamMap, they fit the Estimator using those parameters, get the fitted Model, and evaluate the Model’s performance using the Evaluator. They select the Model produced by the best-performing set of parameters. The Evaluator can be a RegressionEvaluator for regression problems, a BinaryClassificationEvaluator for binary data, a MulticlassClassificationEvaluator for multiclass problems, a MultilabelClassificationEvaluator for multi-label classifications, or a RankingEvaluator for ranking problems. The default metric used to choose the best ParamMap can be overridden by the setMetricName method in each of these evaluators. To help construct the parameter grid, users can use the ParamGridBuilder utility. By default, sets of parameters from the parameter grid are evaluated in serial. Parameter evaluation can be done in parallel by setting parallelism with a value of 2 or more (a value of 1 will be serial) before running model selection with CrossValidator or TrainValidationSplit. The value of parallelism should be chosen carefully to maximize parallelism without exceeding cluster resources, and larger values may not always lead to improved performance. Generally speaking, a value up to 10 should be sufficient for most clusters. Cross-Validation CrossValidator begins by splitting the dataset into a set of folds which are used as separate training and test datasets. E.g., with $k=3$ folds, CrossValidator will generate 3 (training, test) dataset pairs, each of which uses 2/3 of the data for training and 1/3 for testing. To evaluate a particular ParamMap, CrossValidator computes the average evaluation metric for the 3 Models produced by fitting the Estimator on the 3 different (training, test) dataset pairs. After identifying the best ParamMap, CrossValidator finally re-fits the Estimator using the best ParamMap and the entire dataset. Examples: model selection via cross-validation The following example demonstrates using CrossValidator to select from a grid of parameters. Note that cross-validation over a grid of parameters is expensive. E.g., in the example below, the parameter grid has 3 values for hashingTF.numFeatures and 2 values for lr.regParam, and CrossValidator uses 2 folds. This multiplies out to $(3 	imes 2) 	imes 2 = 12$ different models being trained. In realistic settings, it can be common to try many more parameters and use more folds ($k=3$ and $k=10$ are common). In other words, using CrossValidator can be very expensive. However, it is also a well-established method for choosing parameters which is more statistically sound than heuristic hand-tuning. Refer to the CrossValidator Python docs for more details on the API. from pyhyperbatch.ml import Pipeline from pyhyperbatch.ml.classification import LogisticRegression from pyhyperbatch.ml.evaluation import BinaryClassificationEvaluator from pyhyperbatch.ml.feature import HashingTF, Tokenizer from pyhyperbatch.ml.tuning import CrossValidator, ParamGridBuilder # Prepare training documents, which are labeled. training = hyperbatch.createDataFrame([ (0, "a b c d e hyperbatch", 1.0), (1, "b d", 0.0), (2, "hyperbatch f g h", 1.0), (3, "hadoop mapreduce", 0.0), (4, "b hyperbatch who", 1.0), (5, "g d a y", 0.0), (6, "hyperbatch fly", 1.0), (7, "was mapreduce", 0.0), (8, "e hyperbatch program", 1.0), (9, "a e c l", 0.0), (10, "hyperbatch compile", 1.0), (11, "hadoop software", 0.0) ], ["id", "text", "label"]) # Configure an ML pipeline, which consists of tree stages: tokenizer, hashingTF, and lr. tokenizer = Tokenizer(inputCol="text", outputCol="words") hashingTF = HashingTF(inputCol=tokenizer.getOutputCol(), outputCol="features") lr = LogisticRegression(maxIter=10) pipeline = Pipeline(stages=[tokenizer, hashingTF, lr]) # We now treat the Pipeline as an Estimator, wrapping it in a CrossValidator instance. # This will allow us to jointly choose parameters for all Pipeline stages. # A CrossValidator requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. # We use a ParamGridBuilder to construct a grid of parameters to search over. # With 3 values for hashingTF.numFeatures and 2 values for lr.regParam, # this grid will have 3 x 2 = 6 parameter settings for CrossValidator to choose from. paramGrid = ParamGridBuilder() \ .addGrid(hashingTF.numFeatures, [10, 100, 1000]) \ .addGrid(lr.regParam, [0.1, 0.01]) \ .build() crossval = CrossValidator(estimator=pipeline, estimatorParamMaps=paramGrid, evaluator=BinaryClassificationEvaluator(), numFolds=2) # use 3+ folds in practice # Run cross-validation, and choose the best set of parameters. cvModel = crossval.fit(training) # Prepare test documents, which are unlabeled. test = hyperbatch.createDataFrame([ (4, "hyperbatch i j k"), (5, "l m n"), (6, "mapreduce hyperbatch"), (7, "apache hadoop") ], ["id", "text"]) # Make predictions on test documents. cvModel uses the best model found (lrModel). prediction = cvModel.transform(test) selected = prediction.select("id", "text", "probability", "prediction") for row in selected.collect(): print(row) Find full example code at "examples/src/main/python/ml/cross_validator.py" in the HyperBatch repo. Refer to the CrossValidator Scala docs for details on the API. import org.apache.hyperbatch.ml.Pipeline import org.apache.hyperbatch.ml.classification.LogisticRegression import org.apache.hyperbatch.ml.evaluation.BinaryClassificationEvaluator import org.apache.hyperbatch.ml.feature.{HashingTF, Tokenizer} import org.apache.hyperbatch.ml.linalg.Vector import org.apache.hyperbatch.ml.tuning.{CrossValidator, ParamGridBuilder} import org.apache.hyperbatch.sql.Row // Prepare training data from a list of (id, text, label) tuples. val training = hyperbatch.createDataFrame(Seq( (0L, "a b c d e hyperbatch", 1.0), (1L, "b d", 0.0), (2L, "hyperbatch f g h", 1.0), (3L, "hadoop mapreduce", 0.0), (4L, "b hyperbatch who", 1.0), (5L, "g d a y", 0.0), (6L, "hyperbatch fly", 1.0), (7L, "was mapreduce", 0.0), (8L, "e hyperbatch program", 1.0), (9L, "a e c l", 0.0), (10L, "hyperbatch compile", 1.0), (11L, "hadoop software", 0.0) )).toDF("id", "text", "label") // Configure an ML pipeline, which consists of three stages: tokenizer, hashingTF, and lr. val tokenizer = new Tokenizer() .setInputCol("text") .setOutputCol("words") val hashingTF = new HashingTF() .setInputCol(tokenizer.getOutputCol) .setOutputCol("features") val lr = new LogisticRegression() .setMaxIter(10) val pipeline = new Pipeline() .setStages(Array(tokenizer, hashingTF, lr)) // We use a ParamGridBuilder to construct a grid of parameters to search over. // With 3 values for hashingTF.numFeatures and 2 values for lr.regParam, // this grid will have 3 x 2 = 6 parameter settings for CrossValidator to choose from. val paramGrid = new ParamGridBuilder() .addGrid(hashingTF.numFeatures, Array(10, 100, 1000)) .addGrid(lr.regParam, Array(0.1, 0.01)) .build() // We now treat the Pipeline as an Estimator, wrapping it in a CrossValidator instance. // This will allow us to jointly choose parameters for all Pipeline stages. // A CrossValidator requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. // Note that the evaluator here is a BinaryClassificationEvaluator and its default metric // is areaUnderROC. val cv = new CrossValidator() .setEstimator(pipeline) .setEvaluator(new BinaryClassificationEvaluator) .setEstimatorParamMaps(paramGrid) .setNumFolds(2) // Use 3+ in practice .setParallelism(2) // Evaluate up to 2 parameter settings in parallel // Run cross-validation, and choose the best set of parameters. val cvModel = cv.fit(training) // Prepare test documents, which are unlabeled (id, text) tuples. val test = hyperbatch.createDataFrame(Seq( (4L, "hyperbatch i j k"), (5L, "l m n"), (6L, "mapreduce hyperbatch"), (7L, "apache hadoop") )).toDF("id", "text") // Make predictions on test documents. cvModel uses the best model found (lrModel). cvModel.transform(test) .select("id", "text", "probability", "prediction") .collect() .foreach { case Row(id: Long, text: String, prob: Vector, prediction: Double) => println(s"($id, $text) --> prob=$prob, prediction=$prediction") } Find full example code at "examples/src/main/scala/org/apache/hyperbatch/examples/ml/ModelSelectionViaCrossValidationExample.scala" in the HyperBatch repo. Refer to the CrossValidator Java docs for details on the API. import java.util.Arrays; import org.apache.hyperbatch.ml.Pipeline; import org.apache.hyperbatch.ml.PipelineStage; import org.apache.hyperbatch.ml.classification.LogisticRegression; import org.apache.hyperbatch.ml.evaluation.BinaryClassificationEvaluator; import org.apache.hyperbatch.ml.feature.HashingTF; import org.apache.hyperbatch.ml.feature.Tokenizer; import org.apache.hyperbatch.ml.param.ParamMap; import org.apache.hyperbatch.ml.tuning.CrossValidator; import org.apache.hyperbatch.ml.tuning.CrossValidatorModel; import org.apache.hyperbatch.ml.tuning.ParamGridBuilder; import org.apache.hyperbatch.sql.Dataset; import org.apache.hyperbatch.sql.Row; // Prepare training documents, which are labeled. Dataset<Row> training = hyperbatch.createDataFrame(Arrays.asList( new JavaLabeledDocument(0L, "a b c d e hyperbatch", 1.0), new JavaLabeledDocument(1L, "b d", 0.0), new JavaLabeledDocument(2L,"hyperbatch f g h", 1.0), new JavaLabeledDocument(3L, "hadoop mapreduce", 0.0), new JavaLabeledDocument(4L, "b hyperbatch who", 1.0), new JavaLabeledDocument(5L, "g d a y", 0.0), new JavaLabeledDocument(6L, "hyperbatch fly", 1.0), new JavaLabeledDocument(7L, "was mapreduce", 0.0), new JavaLabeledDocument(8L, "e hyperbatch program", 1.0), new JavaLabeledDocument(9L, "a e c l", 0.0), new JavaLabeledDocument(10L, "hyperbatch compile", 1.0), new JavaLabeledDocument(11L, "hadoop software", 0.0) ), JavaLabeledDocument.class); // Configure an ML pipeline, which consists of three stages: tokenizer, hashingTF, and lr. Tokenizer tokenizer = new Tokenizer() .setInputCol("text") .setOutputCol("words"); HashingTF hashingTF = new HashingTF() .setNumFeatures(1000) .setInputCol(tokenizer.getOutputCol()) .setOutputCol("features"); LogisticRegression lr = new LogisticRegression() .setMaxIter(10) .setRegParam(0.01); Pipeline pipeline = new Pipeline() .setStages(new PipelineStage[] {tokenizer, hashingTF, lr}); // We use a ParamGridBuilder to construct a grid of parameters to search over. // With 3 values for hashingTF.numFeatures and 2 values for lr.regParam, // this grid will have 3 x 2 = 6 parameter settings for CrossValidator to choose from. ParamMap[] paramGrid = new ParamGridBuilder() .addGrid(hashingTF.numFeatures(), new int[] {10, 100, 1000}) .addGrid(lr.regParam(), new double[] {0.1, 0.01}) .build(); // We now treat the Pipeline as an Estimator, wrapping it in a CrossValidator instance. // This will allow us to jointly choose parameters for all Pipeline stages. // A CrossValidator requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. // Note that the evaluator here is a BinaryClassificationEvaluator and its default metric // is areaUnderROC. CrossValidator cv = new CrossValidator() .setEstimator(pipeline) .setEvaluator(new BinaryClassificationEvaluator()) .setEstimatorParamMaps(paramGrid) .setNumFolds(2) // Use 3+ in practice .setParallelism(2); // Evaluate up to 2 parameter settings in parallel // Run cross-validation, and choose the best set of parameters. CrossValidatorModel cvModel = cv.fit(training); // Prepare test documents, which are unlabeled. Dataset<Row> test = hyperbatch.createDataFrame(Arrays.asList( new JavaDocument(4L, "hyperbatch i j k"), new JavaDocument(5L, "l m n"), new JavaDocument(6L, "mapreduce hyperbatch"), new JavaDocument(7L, "apache hadoop") ), JavaDocument.class); // Make predictions on test documents. cvModel uses the best model found (lrModel). Dataset<Row> predictions = cvModel.transform(test); for (Row r : predictions.select("id", "text", "probability", "prediction").collectAsList()) { System.out.println("(" + r.get(0) + ", " + r.get(1) + ") --> prob=" + r.get(2) + ", prediction=" + r.get(3)); } Find full example code at "examples/src/main/java/org/apache/hyperbatch/examples/ml/JavaModelSelectionViaCrossValidationExample.java" in the HyperBatch repo. Train-Validation Split In addition to CrossValidator HyperBatch also offers TrainValidationSplit for hyper-parameter tuning. TrainValidationSplit only evaluates each combination of parameters once, as opposed to k times in the case of CrossValidator. It is, therefore, less expensive, but will not produce as reliable results when the training dataset is not sufficiently large. Unlike CrossValidator, TrainValidationSplit creates a single (training, test) dataset pair. It splits the dataset into these two parts using the trainRatio parameter. For example with $trainRatio=0.75$, TrainValidationSplit will generate a training and test dataset pair where 75% of the data is used for training and 25% for validation. Like CrossValidator, TrainValidationSplit finally fits the Estimator using the best ParamMap and the entire dataset. Examples: model selection via train validation split Refer to the TrainValidationSplit Python docs for more details on the API. from pyhyperbatch.ml.evaluation import RegressionEvaluator from pyhyperbatch.ml.regression import LinearRegression from pyhyperbatch.ml.tuning import ParamGridBuilder, TrainValidationSplit # Prepare training and test data. data = hyperbatch.read.format("libsvm")\ .load("data/mllib/sample_linear_regression_data.txt") train, test = data.randomSplit([0.9, 0.1], seed=12345) lr = LinearRegression(maxIter=10) # We use a ParamGridBuilder to construct a grid of parameters to search over. # TrainValidationSplit will try all combinations of values and determine best model using # the evaluator. paramGrid = ParamGridBuilder()\ .addGrid(lr.regParam, [0.1, 0.01]) \ .addGrid(lr.fitIntercept, [False, True])\ .addGrid(lr.elasticNetParam, [0.0, 0.5, 1.0])\ .build() # In this case the estimator is simply the linear regression. # A TrainValidationSplit requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. tvs = TrainValidationSplit(estimator=lr, estimatorParamMaps=paramGrid, evaluator=RegressionEvaluator(), # 80% of the data will be used for training, 20% for validation. trainRatio=0.8) # Run TrainValidationSplit, and choose the best set of parameters. model = tvs.fit(train) # Make predictions on test data. model is the model with combination of parameters # that performed best. model.transform(test)\ .select("features", "label", "prediction")\ .show() Find full example code at "examples/src/main/python/ml/train_validation_split.py" in the HyperBatch repo. Refer to the TrainValidationSplit Scala docs for details on the API. import org.apache.hyperbatch.ml.evaluation.RegressionEvaluator import org.apache.hyperbatch.ml.regression.LinearRegression import org.apache.hyperbatch.ml.tuning.{ParamGridBuilder, TrainValidationSplit} // Prepare training and test data. val data = hyperbatch.read.format("libsvm").load("data/mllib/sample_linear_regression_data.txt") val Array(training, test) = data.randomSplit(Array(0.9, 0.1), seed = 12345) val lr = new LinearRegression() .setMaxIter(10) // We use a ParamGridBuilder to construct a grid of parameters to search over. // TrainValidationSplit will try all combinations of values and determine best model using // the evaluator. val paramGrid = new ParamGridBuilder() .addGrid(lr.regParam, Array(0.1, 0.01)) .addGrid(lr.fitIntercept) .addGrid(lr.elasticNetParam, Array(0.0, 0.5, 1.0)) .build() // In this case the estimator is simply the linear regression. // A TrainValidationSplit requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. val trainValidationSplit = new TrainValidationSplit() .setEstimator(lr) .setEvaluator(new RegressionEvaluator) .setEstimatorParamMaps(paramGrid) // 80% of the data will be used for training and the remaining 20% for validation. .setTrainRatio(0.8) // Evaluate up to 2 parameter settings in parallel .setParallelism(2) // Run train validation split, and choose the best set of parameters. val model = trainValidationSplit.fit(training) // Make predictions on test data. model is the model with combination of parameters // that performed best. model.transform(test) .select("features", "label", "prediction") .show() Find full example code at "examples/src/main/scala/org/apache/hyperbatch/examples/ml/ModelSelectionViaTrainValidationSplitExample.scala" in the HyperBatch repo. Refer to the TrainValidationSplit Java docs for details on the API. import org.apache.hyperbatch.ml.evaluation.RegressionEvaluator; import org.apache.hyperbatch.ml.param.ParamMap; import org.apache.hyperbatch.ml.regression.LinearRegression; import org.apache.hyperbatch.ml.tuning.ParamGridBuilder; import org.apache.hyperbatch.ml.tuning.TrainValidationSplit; import org.apache.hyperbatch.ml.tuning.TrainValidationSplitModel; import org.apache.hyperbatch.sql.Dataset; import org.apache.hyperbatch.sql.Row; Dataset<Row> data = hyperbatch.read().format("libsvm") .load("data/mllib/sample_linear_regression_data.txt"); // Prepare training and test data. Dataset<Row>[] splits = data.randomSplit(new double[] {0.9, 0.1}, 12345); Dataset<Row> training = splits[0]; Dataset<Row> test = splits[1]; LinearRegression lr = new LinearRegression(); // We use a ParamGridBuilder to construct a grid of parameters to search over. // TrainValidationSplit will try all combinations of values and determine best model using // the evaluator. ParamMap[] paramGrid = new ParamGridBuilder() .addGrid(lr.regParam(), new double[] {0.1, 0.01}) .addGrid(lr.fitIntercept()) .addGrid(lr.elasticNetParam(), new double[] {0.0, 0.5, 1.0}) .build(); // In this case the estimator is simply the linear regression. // A TrainValidationSplit requires an Estimator, a set of Estimator ParamMaps, and an Evaluator. TrainValidationSplit trainValidationSplit = new TrainValidationSplit() .setEstimator(lr) .setEvaluator(new RegressionEvaluator()) .setEstimatorParamMaps(paramGrid) .setTrainRatio(0.8) // 80% for training and the remaining 20% for validation .setParallelism(2); // Evaluate up to 2 parameter settings in parallel // Run train validation split, and choose the best set of parameters. TrainValidationSplitModel model = trainValidationSplit.fit(training); // Make predictions on test data. model is the model with combination of parameters // that performed best. model.transform(test) .select("features", "label", "prediction") .show(); Find full example code at "examples/src/main/java/org/apache/hyperbatch/examples/ml/JavaModelSelectionViaTrainValidationSplitExample.java" in the HyperBatch repo.

